package io.xeros.solo;
import io.xeros.*;import io.xeros.content.combat.*;import io.xeros.content.combat.core.*;import io.xeros.content.combat.magic.*;import io.xeros.content.combat.range.*;import io.xeros.content.combat.specials.*;import io.xeros.content.combat.specials.impl.*;import io.xeros.content.combat.weapon.*;import io.xeros.content.bosses.*;import io.xeros.model.*;import io.xeros.model.definitions.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import java.util.*;
public class GearCoverage69Check {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static Player actor(){return WeaponsEquipment69Check.actor();}static void clear(Player p){ToaSoloPlayableCheck.clear(p);}static final Random PROC=new Random(){public double nextDouble(){return 0;}public int nextInt(int bound){return bound-1;}};
 static void variants(){for(int id:new int[]{27277,22486,25733,25738,25739,25741,25862,25865,27235,27238,27241})ok(ItemStats.forId(id).getEquipment().getSlot()>=0&&!ItemDef.forId(id).getName().contains("unknown"),"Missing variant "+id);ok(WeaponData.forItemId(25739)==WeaponData.SCYTHE&&Specials.forWeaponId(25736)==null,"Scythe variant family/illegal special");Player p=actor();p.getItems().addItem(27226,1);p.getItems().addItem(27269,1);ok(SoloBossCrafting.useItem(p,27226,27269)&&p.getItems().getInventoryCount(27235)==1&&p.getItems().getInventoryCount(27226)==0,"Masori mask fortification");p.getItems().addItem(11828,1);p.getItems().addItem(2347,1);SoloBossCrafting.useItem(p,11828,2347);ok(p.getItems().getInventoryCount(27269)==4&&p.getItems().getInventoryCount(2347)==1,"Armadylean plates and retained hammer");p.getItems().addItem(27229,1);SoloBossCrafting.useItem(p,27229,27269);ok(p.getItems().getInventoryCount(27238)==1&&p.getItems().getInventoryCount(27269)==0,"Masori body cost");clear(p);System.out.println("GEAR_VARIANTS_REAL_CACHE_DEFINITIONS_EQUIPMENT_STATS_MASORI_COMPONENT_COSTS_PASS");}
 static void powered(){for(int id:new int[]{27275,22323,25731,11907,12899,22288,22292,25865}){Player p=actor();p.playerEquipment[3]=id;p.playerEquipmentN[3]=1;p.setSpellId(-1);p.autocasting=false;p.autocastId=-1;p.getEquipmentChargeLedger().set("e3",1);NPC n=CombatMagicPaymentCheck.target(p);p.attacking.attackEntity(n);ok(p.getEquipmentChargeLedger().equipped()==0&&!p.getDamageQueue().getQueue().isEmpty(),"Powered last charge "+id+" queue="+p.getDamageQueue().getQueue().size()+" charge="+p.getEquipmentChargeLedger().equipped());int hits=p.getDamageQueue().getQueue().size();p.attackTimer=0;p.attacking.attackEntity(n);ok(p.getDamageQueue().getQueue().size()==hits,"Empty powered weapon attacks "+id);n.unregisterInstant();clear(p);}System.out.println("EIGHT_POWERED_WEAPONS_NATIVE_ATTACK_LAST_CHARGE_AND_EMPTY_GUARD_PASS");}
 static void bolts(){Player p=actor(),q=actor();NPC n=new NPC(Npcs.GOBLIN,new Position(p.getX()+1,p.getY(),p.getHeight()));n.getHealth().setMaximumHealth(1000);n.getHealth().reset();q.playerLevel[6]=99;q.playerLevel[5]=99;p.playerEquipment[3]=26374;for(int type=0;type<EnchantedBolts.IDS.length;type++)for(int id:EnchantedBolts.IDS[type]){p.getHealth().reset();p.playerEquipment[13]=id;io.xeros.model.entity.Entity target=type==3||type==4?q:n;EnchantedBolts.Result r=EnchantedBolts.roll(p,target,50,1,new ZaryteCrossbow(),PROC);ok(r.kind==type&&r.accurate,"Bolt type "+id+" kind="+r.kind);if(type==6)ok(r.amount==110,"Ruby cap");Damage hit=new Damage(40);hit.boltKind=r.kind;hit.boostedBolt=r.boosted;int hp=p.getHealth().getCurrentHealth();EnchantedBolts.impact(p,target,hit,40);if(type==6)ok(p.getHealth().getCurrentHealth()==hp-hp/10,"Ruby self cost");ok(hit.boltKind==-1,"Effect remains pending "+id);EnchantedBolts.impact(p,target,hit,40);}
 ok(Math.abs(EnchantedBolts.chance(6,true,true,false)-.066)<1e-10,"Kandarin multiplier");ok(EnchantedBolts.chance(6,true,false,true)==.12,"Armadyl chance");p.getHealth().setCurrentHealth(9);p.playerEquipment[13]=EnchantedBolts.IDS[6][0];ok(EnchantedBolts.roll(p,n,50,1,new ZaryteCrossbow(),PROC).kind==-1,"Ruby low HP guard");n.unregisterInstant();clear(p);clear(q);System.out.println("TWENTY_ENCHANTED_BOLTS_EFFECT_SELECTION_ONCE_IMPACT_ZARYTE_RUBY_COST_CAP_DIARY_MULTIPLIER_PASS");}
 static void defences()throws Exception{Player p=actor();NPC n=new NPC(2,new Position(p.getX()+1,p.getY(),0));n.setAttackType(CombatType.RANGE);p.playerEquipment[0]=22326;p.playerEquipment[4]=22327;p.playerEquipment[7]=22328;p.playerBonus[Bonus.DEFENCE_RANGED.ordinal()]=300;p.playerEquipment[5]=12817;ok(DefensiveEquipment.reduce(p,n,100,Hitmark.HIT,b->0)==65,"Justiciar plus Elysian");ok(DefensiveEquipment.reduce(p,n,100,Hitmark.HIT,b->99)==90,"Elysian failure");ok(DefensiveEquipment.reduce(p,null,100,Hitmark.HIT,b->0)==100,"Poison reduced");p.playerEquipment[3]=21015;p.getCombatConfigs().setAttackStyle(1);p.bulwarkReadyTick=0;ok(DefensiveEquipment.reduce(p,n,100,Hitmark.HIT,b->0)==52,"Bulwark stacked reduction");p.playerEquipment[5]=12821;ok(DefensiveEquipment.prayerLoss(p,9)==5,"Spectral drain rounding");p.getCombatConfigs().setAttackStyle(0);p.bulwarkReadyTick=0;Special spec=Specials.forWeaponId(26219);ok(spec instanceof OsmumtensFang,"Fang registry");p.playerEquipment[3]=26219;p.usingSpecial=true;p.specAmount=10;p.playerEquipmentN[3]=1;p.attacking.attackEntity(n);ok(p.specAmount==7.5&&!p.getDamageQueue().getQueue().isEmpty(),"Native Fang special energy/queue "+p.specAmount);n.unregisterInstant();clear(p);System.out.println("JUSTICIAR_ELYSIAN_BULWARK_SPECTRAL_AND_NATIVE_FANG_SPECIAL_DISPATCH_PASS");}
 public static void main(String[]args)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");Server.startServerless();variants();powered();bolts();defences();System.out.println("GEAR_COVERAGE69_PASS");System.exit(0);}
}